    const existing = items.value.find((i) => i.id === item.id)
    if (existing) {
      existing.quantity += quantity
    } else {
      items.value.push({ ...item, quantity })
    }
  }

  function remove(id: string) {
    const index = items.value.findIndex((i) => i.id === id)
    if (index !== -1) {
      items.value.splice(index, 1)
    }
  }

  function clear() {
    items.value = []
  }

  return {
    items,
    total,
    itemCount,
    add,
    remove,
    clear,
  }
})
